head.script:
scwin.SearchBox1_onresetclick = function(e) {
    //alert("닫기");
    alertIsShowed = "닫기";
};
scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
	scwin.simulateWrapper("#SearchBox1___input", "key-sequence", {
		sequence: "test"
	});
}		
scwin.setSimulate2 = function() {
	scwin.simulateWrapper("#SearchBox1___reset", "drag-n-drop", {
		dx: 0,
		dy: 0
	});
}
scwin.checkVal1 = function() {
    return alertIsShowed == "닫기";
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.alertIsShowed = "";
}
